from pathlib import Path
from collections import Counter
import json
out=Path(__file__).parent
rows=json.loads((out/'observations.json').read_text());summary=[]
assets={'Script','Stylesheet','Image','Font','Media'}
for p in rows:
 for n in p['navigations']:
  start=n['startHostMs']; events=[e for e in n['network'] if e['hostMs']<=n['observationEndHostMs']]
  cached={e.get('ordinal') for e in events if e['kind']=='cache' or e['kind']=='response' and e.get('fromDiskCache')}
  cached.discard(None)
  last=max((e['hostMs'] for e in events if e.get('type') in assets),default=None)
  cpu=lambda s:(s['userNs']+s['systemNs'])/1e6
  r={'sharedMiB':p['cacheMiB'],'privateMiB':64,'processOrdinal':p['processOrdinal'],'navigationOrdinal':n['navigationOrdinal'],'pid':p['pid'],'startEpochMs':n['before']['epochMs'],'usableMs':n['usableHostMs']-start,'dclMs':n.get('dclHostMs',start)-start if 'dclHostMs' in n else None,'loadMs':n.get('loadHostMs',start)-start if 'loadHostMs' in n else None,'observedThroughMs':n['observationEndHostMs']-start,'postUsabilityHorizonMs':n['observationEndHostMs']-n['usableHostMs'],'lastObservedAssetEventMs':None if last is None else last-start,'requestTypes':dict(Counter(e.get('type','Unknown') for e in events if e['kind']=='request')),'cacheHitRequestCount':len(cached),'cdpDecodedDataBytes':sum(e.get('dataLength',0) for e in events if e['kind']=='data'),'terminalEncodedBodyBytes':sum(e.get('encodedDataLength',0) for e in events if e['kind']=='finished'),'failedCount':sum(e['kind']=='failed' for e in events),'browserCpuToUsableMs':cpu(n['usable'])-cpu(n['before']),'browserCpuToHorizonMs':cpu(n['end'])-cpu(n['before']),'rssBeforeMiB':n['before']['rssKiB']/1024,'rssUsableMiB':n['usable']['rssKiB']/1024,'rssEndMiB':n['end']['rssKiB']/1024,'footprintEndMiB':n['end']['footprintKiB']/1024,'domReadiness':n.get('domReady')}
  summary.append(r)
(out/'summary.json').write_text(json.dumps(summary,indent=2))
lines=['# Exact-main diagnostic profile navigation','', 'Browser eabee486709f79167520a46887cd6f303b26711d, signed binary66e7448e07666176e9650ba714cba04ecc570c65f6e6139ad5bd759f5b49ad88. Explicit allow-jit and JSC_usePollingTraps=true. All12 navigations completed the seven original profile-settings assertions. This external hard-navigation diagnostic is not an unchanged suite run.','', '|Shared MiB|Process|Nav|Usable ms|DCL ms|Load ms|Browser CPU to usable ms|RSS usable MiB|Cache-hit requests|Last asset ms|','|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
for r in summary:
 vals=[r[k] for k in ('sharedMiB','processOrdinal','navigationOrdinal','usableMs','dclMs','loadMs','browserCpuToUsableMs','rssUsableMiB','cacheHitRequestCount','lastObservedAssetEventMs')]
 lines.append('|'+ '|'.join('n/a' if x is None else f'{x:.1f}' if isinstance(x,float) else str(x) for x in vals)+'|')
lines+=['','Private context cache remains64MiB in both lanes. Shared0 is not all-cache-off. Process1/2 are fresh; nav2/3 reuse the same context/page and retain caches. No route/autosave mutation. Original TOS f9f fixtures, assertions, auth and manifest unchanged; nativePG template reused from same UTC date/fixture ledger, per-run DB cleanup0 remaining, three ledger templates retained. Setup/auth/DB costs are outside navigation windows and in setup-timings/coverage.log.','', 'Usable time is the completion of sequential Playwright assertions and includes polling/host scheduling. DCL/load are host-observed events; the optional document readiness marker was null for all12 and is unavailable. Network horizon is scheduled1000ms after usability; actual horizon is retained per navigation, not a blocking last-asset deadline. Last asset is the last observed Script/Stylesheet/Image/Font/Media event within that horizon; later activity is outside scope.','', 'CDP dataLength and data-event encodedDataLength both count decoded chunks on this implementation; only dataLength is summed as decoded bytes. loadingFinished encodedDataLength is separately reported as encoded transport body bytes, not total HTTP wire bytes/headers. fromDiskCache means in-memory cache here. Browser native proc_pid_rusage CPU includes all browser threads; it can exceed wall time. RSS is sampled retained memory, not live JS heap, and no forced GC was performed. Sampler launch/reading and observer/assertion instrumentation have overhead; timestamps expose sample windows.','', 'The preceding /private/tmp/lp-profile-nav-eabee486 run lacked allow-jit and is separate diagnostic evidence. No pooled signed/non-JIT speed claim; sequential runs confound drift. No full TOS, general load-performance or memory-leak conclusion.']
(out/'RESULT.md').write_text('\n'.join(lines)+'\n')
print('\n'.join(lines[:19]))
